import assert from 'node:assert/strict';
import { readFileSync, writeFileSync } from 'node:fs';
import { LinearClient } from '@linear/sdk';
const client = new LinearClient({ apiKey: process.env.LINEAR_API_KEY });
const receiptFile = 'linear-records.json';
if (process.argv[2] === 'readback') {
  const saved = JSON.parse(readFileSync(receiptFile, 'utf8'));
  const me = await client.viewer;
  const organization = await client.organization;
  const issue = await client.issue(saved.issue);
  const state = await issue.state;
  const team = await client.team(saved.team);
  assert.equal(me.id, saved.owner);
  assert.equal(issue.id, saved.issue);
  assert.equal(issue.title, 'SDK issue updated');
  assert.equal(issue.description, 'Synthetic issue body');
  assert.equal(issue.priority, 2);
  assert.equal(team.issueCount, 1);
  assert.equal(me.createdIssueCount, 1);
  console.log(JSON.stringify({ retained: true, owner: me.id, organization: organization.id, state: state.id, team: team.id, issue: issue.id }));
} else {
  const me = await client.viewer;
  const organization = await client.organization;
  assert.equal(me.app, false);
  assert.ok(me.id && me.email && me.isMe);
  const madeTeam = await client.createTeam({ name: 'SDK team', key: 'SDK' });
  const team = await madeTeam.team;
  assert.equal(madeTeam.success, true);
  assert.ok(team?.id);
  const madeIssue = await client.createIssue({ teamId: team.id, title: 'SDK issue', description: 'Synthetic issue body' });
  const issue = await madeIssue.issue;
  const state = await issue.state;
  assert.equal(madeIssue.success, true);
  assert.ok(issue?.id);
  assert.equal((await client.updateIssue(issue.id, { title: 'SDK issue updated', priority: 2 })).success, true);
  const got = await client.issue(issue.id);
  assert.equal(got.title, 'SDK issue updated');
  assert.equal(got.description, 'Synthetic issue body');
  assert.equal(got.priority, 2);
  assert.equal((await client.team(team.id)).issueCount, 1);
  assert.equal((await client.viewer).createdIssueCount, 1);
  const saved = { owner: me.id, team: team.id, issue: issue.id };
  writeFileSync(receiptFile, JSON.stringify(saved) + '\n');
  console.log(JSON.stringify({ writtenAndRead: true, organization: organization.id, state: state.id, ...saved }));
}
